class Solution:
    def ladoos(self, root, home, K):
        def dfs(node, parent):
            if not node:
                return None
            if node.data == home:
                self.target = node
            node.parent = parent
            dfs(node.left, node)
            dfs(node.right, node)

        def collect_ladoos(node, dist):
            if not node or dist < 0:
                return 0
            return node.data + collect_ladoos(node.left, dist - 1) + collect_ladoos(node.right, dist - 1)

        self.target = None
        dfs(root, None)
        total_ladoos = 0
        visited = set()
        stack = [(self.target, K)]

        while stack:
            current, distance = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            total_ladoos += collect_ladoos(current, distance)
            if current.parent and distance > 0:
                stack.append((current.parent, distance - 1))

        return total_ladoos
